const ResponsiveDialogState = (args: ResponsiveDialogProps) => {
  const [open, setOpen] = useState(false);

  return (
    <Box>
      <Button onClick={() => setOpen(true)}>Open</Button>
      <ResponsiveDialog open={open} setOpen={setOpen} {...args}>
        {args.children}
      </ResponsiveDialog>
    </Box>
  );
};

